<script>const patientInput=document.querySelector('#patient_id'),dateInput=document.querySelector('#appointment_date'),timeInput=document.querySelector('#appointment_time'),doctorSelect=document.querySelector('#doctor');async function loadDoctors(){doctorSelect.innerHTML='<option value="">Loading…</option>';if(!patientInput.value||!dateInput.value||!timeInput.value){doctorSelect.innerHTML='<option value="">Enter patient, date and time</option>';return}const url=new URL('{{ route('appointments.doctors') }}',location.origin);url.searchParams.set('patient_id',patientInput.value);url.searchParams.set('date',dateInput.value);url.searchParams.set('time',timeInput.value);const response=await fetch(url,{headers:{'Accept':'application/json'}});const doctors=await response.json();doctorSelect.innerHTML='<option value="">Select doctor</option>';for(const doctor of doctors){const option=document.createElement('option');option.value=doctor.id;option.textContent=doctor.first_name+' '+doctor.last_name;doctorSelect.append(option)}if(!doctors.length)doctorSelect.innerHTML='<option value="">No doctors available at this time</option>'}patientInput.addEventListener('input',loadDoctors);dateInput.addEventListener('change',loadDoctors);timeInput.addEventListener('change',loadDoctors);</script>
@endif
@if(auth()->user()->role->name==='Doctor')<script>document.querySelectorAll('.add-medication').forEach(button=>button.addEventListener('click',()=>{const rows=button.closest('form').querySelector('.medication-rows'),index=rows.children.length,row=rows.firstElementChild.cloneNode(true);row.querySelectorAll('input').forEach(input=>{input.value='';input.name=input.name.replace(/medications\[0\]/,`medications[${index}]`)});row.querySelector('select').name=`medications[${index}][time_slot]`;rows.append(row)}))</script>@endif @endsection
